BEGIN;
CREATE TABLE IF NOT EXISTS security_baseline_models(id UUID PRIMARY KEY,organization_id UUID NOT NULL,metric TEXT NOT NULL,model_version INTEGER NOT NULL,sample_count INTEGER NOT NULL,mean DOUBLE PRECISION NOT NULL,m2 DOUBLE PRECISION NOT NULL,last_observed_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,metric,model_version));
CREATE TABLE IF NOT EXISTS security_baseline_anomalies(id UUID PRIMARY KEY,organization_id UUID NOT NULL,event_id UUID NOT NULL,metric TEXT NOT NULL,model_version INTEGER NOT NULL,observed_value DOUBLE PRECISION NOT NULL,baseline_mean DOUBLE PRECISION NOT NULL,baseline_stddev DOUBLE PRECISION NOT NULL,z_score DOUBLE PRECISION NOT NULL,anomaly_score DOUBLE PRECISION NOT NULL,explanation JSONB NOT NULL,observed_at TIMESTAMPTZ NOT NULL,UNIQUE(organization_id,event_id,metric,model_version));
CREATE TABLE IF NOT EXISTS security_behavior_detections(id UUID PRIMARY KEY,organization_id UUID NOT NULL,event_id UUID NOT NULL,rule_code TEXT NOT NULL,rule_version INTEGER NOT NULL,severity TEXT NOT NULL,risk_score DOUBLE PRECISION NOT NULL,explanation JSONB NOT NULL,analyst_disposition TEXT,analyst_note TEXT,observed_at TIMESTAMPTZ NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,event_id,rule_code,rule_version));
CREATE TABLE IF NOT EXISTS security_attack_stories(id UUID PRIMARY KEY,organization_id UUID NOT NULL,story_key TEXT NOT NULL,title TEXT NOT NULL,current_version INTEGER NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(organization_id,story_key));
CREATE TABLE IF NOT EXISTS security_attack_story_versions(id UUID PRIMARY KEY,story_id UUID NOT NULL,organization_id UUID NOT NULL,version INTEGER NOT NULL,timeline JSONB NOT NULL,trigger_detection_id UUID,summary JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(story_id,version));
COMMIT;
